struct Handle {
  HANDLE value{INVALID_HANDLE_VALUE};
  Handle()=default; explicit Handle(HANDLE v):value(v){}
  Handle(const Handle&)=delete; Handle& operator=(const Handle&)=delete;
  Handle(Handle&& other) noexcept:value(other.value){other.value=INVALID_HANDLE_VALUE;}
  Handle& operator=(Handle&& other) noexcept{if(this!=&other){if(value!=INVALID_HANDLE_VALUE&&value)CloseHandle(value);value=other.value;other.value=INVALID_HANDLE_VALUE;}return *this;}
  ~Handle(){if(value!=INVALID_HANDLE_VALUE&&value)CloseHandle(value);}
};
struct ScHandle { SC_HANDLE value{}; ~ScHandle(){if(value)CloseServiceHandle(value);} };
struct RegHandle { HKEY value{}; ~RegHandle(){if(value)RegCloseKey(value);} };
struct NcHandle { NCRYPT_HANDLE value{}; ~NcHandle(){if(value)NCryptFreeObject(value);} };

std::string Escape(std::string_view value) {
  std::string out; out.push_back('"');
  for (unsigned char c : value) {
    if (c == '"' || c == '\\') { out.push_back('\\'); out.push_back(static_cast<char>(c)); }
    else if (c >= 0x20 && c < 0x7f) out.push_back(static_cast<char>(c));
    else { char b[7]{}; sprintf_s(b, "\\u%04x", c); out += b; }
  }
  out.push_back('"'); return out;
}
std::string Narrow(std::wstring_view value) {
  if(value.empty()) return {};
  int n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,value.data(),static_cast<int>(value.size()),nullptr,0,nullptr,nullptr);
  if(n<=0)return {};
  std::string out(static_cast<size_t>(n),'\0');
  if(!WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,value.data(),static_cast<int>(value.size()),out.data(),n,nullptr,nullptr))return {};
  return out;
}
std::string Hex(const unsigned char* p,size_t n){static constexpr char h[]="0123456789abcdef";std::string s(n*2,'0');for(size_t i=0;i<n;++i){s[i*2]=h[p[i]>>4];s[i*2+1]=h[p[i]&15];}return s;}
std::string ErrorValue(DWORD code){return "{\"error\":"+std::to_string(code)+",\"status\":\"unavailable\"}";}
std::string EmbeddedPlan(){HRSRC resource=FindResourceW(nullptr,MAKEINTRESOURCEW(101),RT_RCDATA);if(!resource)return{};HGLOBAL loaded=LoadResource(nullptr,resource);const auto size=SizeofResource(nullptr,resource);const auto*bytes=static_cast<const char*>(LockResource(loaded));return bytes&&size?std::string(bytes,size):std::string{};}
std::string JsonStringField(std::string_view object,std::string_view key){const std::string prefix="\""+std::string(key)+"\":\"";auto p=object.find(prefix);if(p==std::string_view::npos)return{};p+=prefix.size();std::string out;for(;p<object.size();++p){char c=object[p];if(c=='"')return out;if(c=='\\'&&p+1<object.size()){char next=object[++p];if(next=='"'||next=='\\'||next=='/')out.push_back(next);else return{};}else out.push_back(c);}return{};}
struct ScopeEntry{std::string id,kind,destination;};
std::vector<ScopeEntry> FixedScope(){const auto plan=EmbeddedPlan();std::vector<ScopeEntry> out;size_t cursor=plan.find("\"proposed\":[");while(cursor!=std::string::npos){auto idPos=plan.find("\"resourceId\":\"",cursor);if(idPos==std::string::npos)break;auto end=plan.find("\"successExitCodes\"",idPos);if(end==std::string::npos)break;auto begin=plan.rfind("{\"desired\"",idPos);if(begin==std::string::npos)break;std::string_view item(plan.data()+begin,end-begin);auto id=JsonStringField(item,"resourceId"),kind=JsonStringField(item,"kind"),destination=JsonStringField(item,"destination");if(id.empty()||kind.empty())return{};out.push_back({id,kind,destination});cursor=end;}return out;}

std::string TokenSnapshot(){
  Handle token{nullptr}; if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&token.value))return ErrorValue(GetLastError());
  TOKEN_ELEVATION elevation{};DWORD used{};if(!GetTokenInformation(token.value,TokenElevation,&elevation,sizeof(elevation),&used))return ErrorValue(GetLastError());
  DWORD size{};GetTokenInformation(token.value,TokenUser,nullptr,0,&size);std::vector<unsigned char> user(size);if(!GetTokenInformation(token.value,TokenUser,user.data(),size,&size))return ErrorValue(GetLastError());
  LPWSTR sid{};if(!ConvertSidToStringSidW(reinterpret_cast<TOKEN_USER*>(user.data())->User.Sid,&sid))return ErrorValue(GetLastError());std::string sidText=Narrow(sid);LocalFree(sid);
  GetTokenInformation(token.value,TokenPrivileges,nullptr,0,&size);std::vector<unsigned char> raw(size);std::vector<std::string> names;
  if(GetTokenInformation(token.value,TokenPrivileges,raw.data(),size,&size)){auto*p=reinterpret_cast<TOKEN_PRIVILEGES*>(raw.data());for(DWORD i=0;i<p->PrivilegeCount;++i){wchar_t name[128]{};DWORD chars=128;if(LookupPrivilegeNameW(nullptr,&p->Privileges[i].Luid,name,&chars))names.push_back(Narrow(std::wstring_view(name,chars))+":"+std::to_string(p->Privileges[i].Attributes));}}
  std::sort(names.begin(),names.end());std::string list="[";for(size_t i=0;i<names.size();++i){if(i)list+=',';list+=Escape(names[i]);}list+=']';
  return "{\"elevated\":"+std::string(elevation.TokenIsElevated?"true":"false")+",\"privileges\":"+list+",\"sid\":"+Escape(sidText)+"}";
}

std::string ServiceSnapshot(const wchar_t* name){
  ScHandle scm{OpenSCManagerW(nullptr,nullptr,SC_MANAGER_CONNECT)};if(!scm.value)return ErrorValue(GetLastError());
  ScHandle service{OpenServiceW(scm.value,name,SERVICE_QUERY_CONFIG|SERVICE_QUERY_STATUS|READ_CONTROL)};if(!service.value)return ErrorValue(GetLastError());
  DWORD bytes{};QueryServiceConfigW(service.value,nullptr,0,&bytes);std::vector<unsigned char> raw(bytes);auto*q=reinterpret_cast<QUERY_SERVICE_CONFIGW*>(raw.data());if(!QueryServiceConfigW(service.value,q,bytes,&bytes))return ErrorValue(GetLastError());
  SERVICE_STATUS_PROCESS status{};if(!QueryServiceStatusEx(service.value,SC_STATUS_PROCESS_INFO,reinterpret_cast<BYTE*>(&status),sizeof(status),&bytes))return ErrorValue(GetLastError());
  std::wstring privileges;QueryServiceConfig2W(service.value,SERVICE_CONFIG_REQUIRED_PRIVILEGES_INFO,nullptr,0,&bytes);if(bytes){std::vector<unsigned char> p(bytes);if(QueryServiceConfig2W(service.value,SERVICE_CONFIG_REQUIRED_PRIVILEGES_INFO,p.data(),bytes,&bytes)){auto*s=reinterpret_cast<SERVICE_REQUIRED_PRIVILEGES_INFOW*>(p.data())->pmszRequiredPrivileges;if(s)for(;*s;s+=wcslen(s)+1){if(!privileges.empty())privileges+=L';';privileges+=s;}}}
  DWORD sidType=0;SERVICE_SID_INFO si{};bytes=sizeof(si);if(QueryServiceConfig2W(service.value,SERVICE_CONFIG_SERVICE_SID_INFO,reinterpret_cast<BYTE*>(&si),bytes,&bytes))sidType=si.dwServiceSidType;
  SERVICE_DELAYED_AUTO_START_INFO delayed{};bytes=sizeof(delayed);QueryServiceConfig2W(service.value,SERVICE_CONFIG_DELAYED_AUTO_START_INFO,reinterpret_cast<BYTE*>(&delayed),bytes,&bytes);
  DWORD secBytes{};QueryServiceObjectSecurity(service.value,DACL_SECURITY_INFORMATION|OWNER_SECURITY_INFORMATION,nullptr,0,&secBytes);std::vector<unsigned char> sec(secBytes);std::string sddl;
  if(secBytes&&QueryServiceObjectSecurity(service.value,DACL_SECURITY_INFORMATION|OWNER_SECURITY_INFORMATION,reinterpret_cast<PSECURITY_DESCRIPTOR>(sec.data()),secBytes,&secBytes)){LPWSTR text{};if(ConvertSecurityDescriptorToStringSecurityDescriptorW(sec.data(),SDDL_REVISION_1,DACL_SECURITY_INFORMATION|OWNER_SECURITY_INFORMATION,&text,nullptr)){sddl=Narrow(text);LocalFree(text);}}
  bytes=0;QueryServiceConfig2W(service.value,SERVICE_CONFIG_FAILURE_ACTIONS,nullptr,0,&bytes);DWORD reset=0,actions=0;std::string actionList="[]";if(bytes){std::vector<unsigned char> f(bytes);if(QueryServiceConfig2W(service.value,SERVICE_CONFIG_FAILURE_ACTIONS,f.data(),bytes,&bytes)){auto*fa=reinterpret_cast<SERVICE_FAILURE_ACTIONSW*>(f.data());reset=fa->dwResetPeriod;actions=fa->cActions;actionList="[";for(DWORD i=0;i<fa->cActions;++i){if(i)actionList+=',';actionList+="{\"delayMs\":"+std::to_string(fa->lpsaActions[i].Delay)+",\"type\":"+std::to_string(fa->lpsaActions[i].Type)+"}";}actionList+=']';}}
  SERVICE_FAILURE_ACTIONS_FLAG failureFlag{};bytes=sizeof(failureFlag);QueryServiceConfig2W(service.value,SERVICE_CONFIG_FAILURE_ACTIONS_FLAG,reinterpret_cast<BYTE*>(&failureFlag),bytes,&bytes);
  std::wstring deps;if(q->lpDependencies)for(auto*s=q->lpDependencies;*s;s+=wcslen(s)+1){if(!deps.empty())deps+=L';';deps+=s;}
  return "{\"account\":"+Escape(Narrow(q->lpServiceStartName?q->lpServiceStartName:L""))+",\"binaryPath\":"+Escape(Narrow(q->lpBinaryPathName?q->lpBinaryPathName:L""))+",\"delayedAutoStart\":"+std::string(delayed.fDelayedAutostart?"true":"false")+",\"dependencies\":"+Escape(Narrow(deps))+",\"failureActionCount\":"+std::to_string(actions)+",\"failureActions\":"+actionList+",\"failureFlag\":"+std::string(failureFlag.fFailureActionsOnNonCrashFailures?"true":"false")+",\"failureResetSeconds\":"+std::to_string(reset)+",\"requiredPrivileges\":"+Escape(Narrow(privileges))+",\"sddl\":"+Escape(sddl)+",\"serviceType\":"+std::to_string(q->dwServiceType)+",\"sidType\":"+std::to_string(sidType)+",\"startType\":"+std::to_string(q->dwStartType)+",\"state\":"+std::to_string(status.dwCurrentState)+"}";
}

bool HostileFileState(DWORD attributes,DWORD links,const std::vector<std::string>&streams,LONGLONG bytes){return(attributes&FILE_ATTRIBUTE_REPARSE_POINT)||links!=1||bytes<0||bytes>64LL*1024*1024||streams.size()!=1||(streams[0]!="::$DATA"&&streams[0]!=":$DATA");}

std::string FileSnapshot(const std::wstring& path){
  DWORD attrs=GetFileAttributesW(path.c_str());if(attrs==INVALID_FILE_ATTRIBUTES)return ErrorValue(GetLastError());
  Handle file{CreateFileW(path.c_str(),GENERIC_READ|READ_CONTROL,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS,nullptr)};if(file.value==INVALID_HANDLE_VALUE)return ErrorValue(GetLastError());
  BY_HANDLE_FILE_INFORMATION basic{};FILE_ID_INFO id{};if(!GetFileInformationByHandle(file.value,&basic)||!GetFileInformationByHandleEx(file.value,FileIdInfo,&id,sizeof(id)))return ErrorValue(GetLastError());
  PSECURITY_DESCRIPTOR sd{};PSID owner{};PACL dacl{};std::string sddl;if(GetSecurityInfo(file.value,SE_FILE_OBJECT,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION,&owner,nullptr,&dacl,nullptr,&sd)==ERROR_SUCCESS){LPWSTR text{};if(ConvertSecurityDescriptorToStringSecurityDescriptorW(sd,SDDL_REVISION_1,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION,&text,nullptr)){sddl=Narrow(text);LocalFree(text);}LocalFree(sd);}
  std::vector<std::string> streams;WIN32_FIND_STREAM_DATA data{};HANDLE find=FindFirstStreamW(path.c_str(),FindStreamInfoStandard,&data,0);if(find!=INVALID_HANDLE_VALUE){do{streams.push_back(Narrow(data.cStreamName));}while(FindNextStreamW(find,&data));FindClose(find);}std::sort(streams.begin(),streams.end());std::string sl="[";for(size_t i=0;i<streams.size();++i){if(i)sl+=',';sl+=Escape(streams[i]);}sl+=']';
  LARGE_INTEGER size{};GetFileSizeEx(file.value,&size);std::string hash="";if(!(attrs&FILE_ATTRIBUTE_DIRECTORY)){if(size.QuadPart<0||size.QuadPart>64LL*1024*1024)return ErrorValue(ERROR_FILE_TOO_LARGE);std::vector<char> bytes(static_cast<size_t>(size.QuadPart));DWORD got{};SetFilePointer(file.value,0,nullptr,FILE_BEGIN);if(ReadFile(file.value,bytes.data(),static_cast<DWORD>(bytes.size()),&got,nullptr)&&got==bytes.size())hash=Sha256(std::string_view(bytes.data(),bytes.size()));}
  return "{\"attributes\":"+std::to_string(attrs)+",\"fileId\":"+Escape(Hex(id.FileId.Identifier,16))+",\"hardlinkCount\":"+std::to_string(basic.nNumberOfLinks)+",\"hostileState\":"+std::string(HostileFileState(attrs,basic.nNumberOfLinks,streams,size.QuadPart)?"true":"false")+",\"ownerDaclSddl\":"+Escape(sddl)+",\"sha256\":"+Escape(hash)+",\"size\":"+std::to_string(size.QuadPart)+",\"streams\":"+sl+",\"volumeSerial\":"+std::to_string(id.VolumeSerialNumber)+"}";
}

std::string RegistryValue(HKEY hive,const wchar_t* path,const wchar_t* value){RegHandle key{};LSTATUS s=RegOpenKeyExW(hive,path,0,KEY_QUERY_VALUE|READ_CONTROL,&key.value);if(s!=ERROR_SUCCESS)return ErrorValue(static_cast<DWORD>(s));DWORD type{},bytes{};s=RegGetValueW(key.value,nullptr,value,RRF_RT_ANY,&type,nullptr,&bytes);if(s!=ERROR_SUCCESS)return ErrorValue(static_cast<DWORD>(s));std::vector<unsigned char> data(bytes);s=RegGetValueW(key.value,nullptr,value,RRF_RT_ANY,&type,data.data(),&bytes);if(s!=ERROR_SUCCESS)return ErrorValue(static_cast<DWORD>(s));DWORD secBytes{};RegGetKeySecurity(key.value,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION,nullptr,&secBytes);std::vector<unsigned char> sec(secBytes);std::string sddl;if(secBytes&&RegGetKeySecurity(key.value,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION,reinterpret_cast<PSECURITY_DESCRIPTOR>(sec.data()),&secBytes)==ERROR_SUCCESS){LPWSTR text{};if(ConvertSecurityDescriptorToStringSecurityDescriptorW(sec.data(),SDDL_REVISION_1,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION,&text,nullptr)){sddl=Narrow(text);LocalFree(text);}}std::string effective;if((type==REG_SZ||type==REG_EXPAND_SZ)&&bytes>=sizeof(wchar_t))effective=Narrow(std::wstring_view(reinterpret_cast<const wchar_t*>(data.data()),bytes/sizeof(wchar_t)-1));return "{\"bytes\":"+std::to_string(bytes)+",\"dataHash\":"+Escape(Sha256(std::string_view(reinterpret_cast<char*>(data.data()),bytes)))+",\"effectiveFields\":"+Escape(effective)+",\"ownerDaclSddl\":"+Escape(sddl)+",\"present\":true,\"type\":"+std::to_string(type)+"}";}
std::string ProviderKeySnapshot(const wchar_t* providerName,const wchar_t* name){NcHandle provider{},key{};SECURITY_STATUS s=NCryptOpenStorageProvider(&provider.value,providerName,0);if(s)return ErrorValue(static_cast<DWORD>(s));s=NCryptOpenKey(provider.value,&key.value,name,0,NCRYPT_MACHINE_KEY_FLAG|NCRYPT_SILENT_FLAG);if(s)return ErrorValue(static_cast<DWORD>(s));DWORD policy{},bytes{};s=NCryptGetProperty(key.value,NCRYPT_EXPORT_POLICY_PROPERTY,reinterpret_cast<PBYTE>(&policy),sizeof(policy),&bytes,0);if(s)return ErrorValue(static_cast<DWORD>(s));DWORD blobBytes{};s=NCryptExportKey(key.value,0,BCRYPT_ECCPUBLIC_BLOB,nullptr,nullptr,0,&blobBytes,0);if(s)return ErrorValue(static_cast<DWORD>(s));std::vector<unsigned char> blob(blobBytes);s=NCryptExportKey(key.value,0,BCRYPT_ECCPUBLIC_BLOB,nullptr,blob.data(),blobBytes,&blobBytes,0);if(s)return ErrorValue(static_cast<DWORD>(s));DWORD sdBytes{};NCryptGetProperty(key.value,NCRYPT_SECURITY_DESCR_PROPERTY,nullptr,0,&sdBytes,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION|NCRYPT_SILENT_FLAG);std::vector<unsigned char> sd(sdBytes);std::string sddl;if(sdBytes&&!NCryptGetProperty(key.value,NCRYPT_SECURITY_DESCR_PROPERTY,sd.data(),sdBytes,&sdBytes,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION|NCRYPT_SILENT_FLAG)){LPWSTR text{};if(ConvertSecurityDescriptorToStringSecurityDescriptorW(sd.data(),SDDL_REVISION_1,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION,&text,nullptr)){sddl=Narrow(text);LocalFree(text);}}return "{\"daclOwnerSddl\":"+Escape(sddl)+",\"exportPolicy\":"+std::to_string(policy)+",\"kid\":"+Escape(Sha256(std::string_view(reinterpret_cast<char*>(blob.data()),blob.size())))+",\"machineKey\":true,\"provider\":"+Escape(Narrow(providerName))+"}";}
std::string ProviderEvidence(const wchar_t* providerName,const wchar_t* name,bool&known){const auto observation=ProviderKeySnapshot(providerName,name);known=observation.find("{\"error\":")!=0;return "{\"observation\":"+observation+",\"provider\":"+Escape(Narrow(providerName))+",\"status\":"+Escape(known?"known":"unavailable")+"}";}
std::string KeySnapshot(const wchar_t* name){
  bool platformKnown=false,softwareKnown=false;
  const auto platform=ProviderEvidence(MS_PLATFORM_CRYPTO_PROVIDER,name,platformKnown);
  const auto software=ProviderEvidence(MS_KEY_STORAGE_PROVIDER,name,softwareKnown);
  return "{\"acceptedCount\":"+std::to_string(platformKnown?1:0)+",\"acceptedProvider\":"+Escape(platformKnown?"Microsoft Platform Crypto Provider":"")+",\"configuredProvider\":\"Microsoft Platform Crypto Provider\",\"machineFlag\":"+std::to_string(NCRYPT_MACHINE_KEY_FLAG)+",\"platform\":"+platform+",\"software\":"+software+",\"softwarePresentNotAccepted\":"+std::string(softwareKnown?"true":"false")+"}";
}

std::string CertificateStoreSnapshot(const wchar_t* storeName){HCERTSTORE store=CertOpenStore(CERT_STORE_PROV_SYSTEM_W,0,0,CERT_SYSTEM_STORE_LOCAL_MACHINE|CERT_STORE_READONLY_FLAG,storeName);if(!store)return ErrorValue(GetLastError());std::vector<std::string> thumbprints;PCCERT_CONTEXT cert{};while((cert=CertEnumCertificatesInStore(store,cert))!=nullptr){if(thumbprints.size()>=1024){CertCloseStore(store,0);return ErrorValue(ERROR_BUFFER_OVERFLOW);}unsigned char hash[64]{};DWORD bytes=sizeof(hash);if(CertGetCertificateContextProperty(cert,CERT_SHA256_HASH_PROP_ID,hash,&bytes))thumbprints.push_back(Hex(hash,bytes));}CertCloseStore(store,CERT_CLOSE_STORE_CHECK_FLAG);std::sort(thumbprints.begin(),thumbprints.end());std::string joined,list="[";for(size_t i=0;i<thumbprints.size();++i){if(i){joined+=',';list+=',';}joined+=thumbprints[i];list+=Escape(thumbprints[i]);}list+=']';return "{\"certificateCount\":"+std::to_string(thumbprints.size())+",\"entries\":"+list+",\"thumbprintSetHash\":"+Escape(Sha256(joined))+"}";}

class NativeProvider final:public ObservationProvider{public:bool Observe(std::string&out,std::string&error)const override{
  wchar_t computer[256]{};DWORD chars=256;if(!GetComputerNameW(computer,&chars)){error="computer name read failed";return false;}
  auto object=[](const auto&m){std::string x="{";bool first=true;for(const auto&[k,v]:m){if(!first)x+=',';first=false;x+=Escape(k)+":"+v;}return x+"}";};
  std::map<std::string,std::string> services={{"AegisStellarCustodian",ServiceSnapshot(L"AegisStellarCustodian")},{"AegisStellarExecutionBroker",ServiceSnapshot(L"AegisStellarExecutionBroker")}};
  std::map<std::string,std::string> keys={{"broker",KeySnapshot(L"AegisStellarExecutionBroker-Attestation-P256-v1")},{"issuer",KeySnapshot(L"AegisStellarCustodian-Issuer-P256-v1")}};
  std::map<std::string,std::string> registry={{"installIdentity",RegistryValue(HKEY_LOCAL_MACHINE,L"SOFTWARE\\AEGIS\\Stellar\\v0.1",L"InstallId")},{"releaseIdentity",RegistryValue(HKEY_LOCAL_MACHINE,L"SOFTWARE\\AEGIS\\Stellar\\v0.1",L"ReleaseHash")}};
  std::map<std::string,std::string> firewall={{"brokerRule",RegistryValue(HKEY_LOCAL_MACHINE,L"SYSTEM\\CurrentControlSet\\Services\\SharedAccess\\Parameters\\FirewallPolicy\\FirewallRules",L"AEGIS Stellar Execution Broker")},{"custodianRule",RegistryValue(HKEY_LOCAL_MACHINE,L"SYSTEM\\CurrentControlSet\\Services\\SharedAccess\\Parameters\\FirewallPolicy\\FirewallRules",L"AEGIS Stellar Custodian")}};
  const auto certificateMy=CertificateStoreSnapshot(L"MY"),certificateRoot=CertificateStoreSnapshot(L"ROOT");
  const auto scope=FixedScope();if(scope.size()!=91){error="embedded plan resource correspondence failed";return false;}std::map<std::string,std::string> resources;for(const auto&entry:scope){std::string value;if(entry.kind=="file")value=FileSnapshot(std::wstring(entry.destination.begin(),entry.destination.end()));else if(entry.id=="dir:install"||entry.id=="acl:install"||entry.id=="identity:install-volume")value=FileSnapshot(L"C:\\Program Files\\AEGIS\\Stellar\\v0.1");else if(entry.id=="dir:data"||entry.id=="acl:data")value=FileSnapshot(L"C:\\ProgramData\\AEGIS\\Stellar\\v0.1");else if(entry.id=="service:custodian")value=services.at("AegisStellarCustodian");else if(entry.id=="service:broker")value=services.at("AegisStellarExecutionBroker");else if(entry.id=="key:issuer")value=keys.at("issuer");else if(entry.id=="key:broker")value=keys.at("broker");else if(entry.id=="registry:release"||entry.id=="config:installed-release"){if(registry.at("installIdentity").find("{\"error\":")==0)value=registry.at("installIdentity");else if(registry.at("releaseIdentity").find("{\"error\":")==0)value=registry.at("releaseIdentity");else value="{\"installIdentity\":"+registry.at("installIdentity")+",\"releaseIdentity\":"+registry.at("releaseIdentity")+"}";}else if(entry.id=="certificate:release"){if(certificateMy.find("{\"error\":")==0)value=certificateMy;else if(certificateRoot.find("{\"error\":")==0)value=certificateRoot;else value="{\"entries\":[],\"my\":"+certificateMy+",\"policy\":\"no-authorized-thumbprint\",\"root\":"+certificateRoot+"}";}else if(entry.id=="firewall:custodian")value=firewall.at("custodianRule");else if(entry.id=="firewall:broker")value=firewall.at("brokerRule");else value=ErrorValue(ERROR_NOT_SUPPORTED);const bool unavailable=value.find("{\"error\":")==0||(entry.kind=="key"&&value.find("\"acceptedCount\":0")!=std::string::npos);resources.emplace(entry.id,"{\"kind\":"+Escape(entry.kind)+",\"observation\":"+value+",\"status\":"+Escape(unavailable?"unavailable":"known")+"}");}
  out="{\"host\":{\"architecture\":\"x64\",\"computerName\":"+Escape(Narrow(std::wstring_view(computer,chars)))+",\"installRoot\":\"C:\\\\Program Files\\\\AEGIS\\\\Stellar\\\\v0.1\",\"os\":\"windows\",\"planArtifactHash\":\"sha256:437e6d3dd6343d226825dffe98f00e1e0649987f20ee1b980af21e281dd8b3a8\",\"planHash\":\"sha256:9958eb87768bbf305d0b4a1f859f86ed8cfb5bb94234bc7c82bb98fc65a0a3b0\"},\"resourceCount\":91,\"resources\":"+object(resources)+",\"token\":"+TokenSnapshot()+"}";return true;}};

class FakeProvider final:public ObservationProvider{public:enum class Mode{stable,fail,drift};explicit FakeProvider(Mode mode=Mode::stable):mode_(mode){}bool Observe(std::string&o,std::string&e)const override{if(mode_==Mode::fail){e="injected";return false;}o=mode_==Mode::drift&&calls_++?"{\"fixed\":false}":"{\"fixed\":true}";return true;}private:Mode mode_;mutable unsigned calls_{};};
bool ValidOutputLeaf(std::wstring_view leaf){static constexpr std::array<std::wstring_view,22> reserved={L"CON",L"PRN",L"AUX",L"NUL",L"COM1",L"COM2",L"COM3",L"COM4",L"COM5",L"COM6",L"COM7",L"COM8",L"COM9",L"LPT1",L"LPT2",L"LPT3",L"LPT4",L"LPT5",L"LPT6",L"LPT7",L"LPT8",L"LPT9"};if(leaf!=L"target-host-discovery.canonical.json"||leaf.ends_with(L'.')||leaf.ends_with(L' ')||leaf.find_first_of(L"\\/:")!=std::wstring_view::npos)return false;return std::find(reserved.begin(),reserved.end(),leaf)==reserved.end();}
bool OpenProtectedOutputRoot(std::wstring&root,std::vector<Handle>&held){PWSTR programData{};if(FAILED(SHGetKnownFolderPath(FOLDERID_ProgramData,KF_FLAG_DONT_VERIFY,nullptr,&programData)))return false;std::wstring base=programData;CoTaskMemFree(programData);if(_wcsicmp(base.c_str(),L"C:\\ProgramData")!=0)return false;const std::array<std::wstring,6> ancestors={L"C:\\",base,base+L"\\AEGIS",base+L"\\AEGIS\\Stellar",base+L"\\AEGIS\\Stellar\\v0.1",base+L"\\AEGIS\\Stellar\\v0.1\\evidence"};for(const auto&path:ancestors){Handle h(CreateFileW(path.c_str(),FILE_READ_ATTRIBUTES|READ_CONTROL,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr));if(h.value==INVALID_HANDLE_VALUE)return false;FILE_ATTRIBUTE_TAG_INFO tag{};FILE_ID_INFO id{};if(!GetFileInformationByHandleEx(h.value,FileAttributeTagInfo,&tag,sizeof(tag))||!GetFileInformationByHandleEx(h.value,FileIdInfo,&id,sizeof(id))||(tag.FileAttributes&FILE_ATTRIBUTE_REPARSE_POINT))return false;held.push_back(std::move(h));}std::string aclError;if(!ProtectedOutputHandleAllowed(held.back().value,nullptr,aclError))return false;root=ancestors.back();return true;}
